package com.ruoyi.paicli.service;

import com.ruoyi.paicli.domain.*;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

public class PcKnowledgeService {
    private final PcStore store;private final PcAccess access;private final PcIdempotency idem;private final PcEvidence evidence;private final PcSessionService sessions;
    public PcKnowledgeService(PcStore s,PcAccess a,PcIdempotency i,PcEvidence e,PcSessionService session){store=s;access=a;idem=i;evidence=e;sessions=session;}
    public List<PcRecord> memories(long user,Long workspace,String scope){if(workspace!=null)access.directory(workspace,user,false);boolean personal="PERSONAL".equalsIgnoreCase(scope)||"global".equalsIgnoreCase(scope);return personal?store.mapper.list(PcTable.MEMORY,null,user,null,null).stream().filter(r->r.getDirectoryContextId()==null&&!Set.of("DELETED","REVOKED_IMPORT","REPLACED").contains(r.getState())&&!r.getKind().equals("SCOPE_LOCK")&&!PcProjectRuleService.isRule(r,store.data(r))).toList():store.mapper.visible(PcTable.MEMORY,user,workspace,false).stream().filter(r->!Set.of("DELETED","REVOKED_IMPORT","REPLACED").contains(r.getState())&&!r.getKind().equals("SCOPE_LOCK")&&!PcProjectRuleService.isRule(r,store.data(r))).toList();}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> save(long user,String key,Map<String,Object> input){return idem.run("user:"+user+":memory",key,input,()->{
        boolean personal=Set.of("PERSONAL","global").contains(PcJson.text(input,"scope"));Long workspace=personal?null:PcJson.number(input,"directoryContextId");if(workspace!=null)access.directory(workspace,user,true);return memoryWrite(user,workspace,null,null,PcJson.text(input,"content"),PcJson.text(input,"source"),"PENDING",input);
    });}
    public Map<String,Object> memoryWrite(long user,Long workspace,Long session,Long task,String fact,String source,String state,Map<String,Object> input){
        if(fact.isBlank()||fact.length()>8192)throw PcException.invalid("记忆应为1至8192字");
        if(workspace!=null)access.directory(workspace,user,true);else{String lockKey="memory-scope:user:"+user;PcRecord lock=store.mapper.findKey(PcTable.MEMORY,lockKey,true);if(lock==null)store.insert(PcTable.MEMORY,null,user,null,null,null,"SCOPE_LOCK","ACTIVE",lockKey,Map.of());}
        String scope=workspace==null?"global":"project";Map<String,Object> data=new LinkedHashMap<>();data.put("content",fact);data.put("fact",fact);data.put("scope",workspace==null?"PERSONAL":"PROJECT");data.put("source",source);String type=input.get("type")==null?"FACT":PcJson.text(input,"type").toUpperCase(Locale.ROOT);if(!Set.of("FACT","CONVERSATION","SUMMARY","TOOL_RESULT").contains(type))throw PcException.invalid("记忆类型非法");data.put("type",type);data.put("timestamp",store.clock.instant().toString());data.put("lastVerifiedAt",store.clock.instant().toString());data.put("tokenCount",estimateTokens(fact));if(input.get("metadata")!=null){Map<String,Object> metadata=PcJson.object(input,"metadata");if(metadata.size()>64||metadata.values().stream().anyMatch(v->!(v instanceof String)||((String)v).length()>8192))throw PcException.invalid("记忆metadata须为有界字符串映射");data.put("metadata",metadata);}if(state.equals("VERIFIED"))data.put("verifiedAt",store.clock.instant().toString());
        List<PcRecord> domain=store.mapper.list(PcTable.MEMORY,workspace,workspace==null?user:null,null,null).stream().filter(r->r.getWorkspaceId()==null&&Objects.equals(r.getOwnerId(),user)&&Objects.equals(r.getDirectoryContextId(),workspace)&&r.getKind().equals("MEMORY")&&!Set.of("FROZEN","DELETED","REVOKED_IMPORT","REPLACED").contains(r.getState())).toList();
        String replace=PcJson.text(input,"replace_id");if(replace.isBlank())replace=PcJson.text(input,"id");PcRecord target=null;if(!replace.isBlank()){String requested=replace;target=domain.stream().filter(r->requested.equals(String.valueOf(r.getId()))).findFirst().orElse(null);if(target==null)return memoryResult("REPLACE_TARGET_NOT_FOUND",candidate(fact,scope),List.of(),null,scope,requested);if(input.containsKey("replaceVersion"))store.version(target,PcJson.number(input,"replaceVersion"));}
        if(target!=null&&PcMemoryFacts.duplicate(PcJson.text(store.data(target),"content"),fact)){if(state.equals("VERIFIED")){Map<String,Object> same=store.data(target);same.put("verifiedAt",store.clock.instant().toString());target.setState("VERIFIED");store.save(PcTable.MEMORY,target,same);}return memoryResult("DUPLICATE",entry(target),List.of(),null,scope,replace);}PcRecord selected=target;PcRecord duplicate=domain.stream().filter(r->selected==null||!r.getId().equals(selected.getId())).filter(r->PcMemoryFacts.duplicate(PcJson.text(store.data(r),"content"),fact)).findFirst().orElse(null);
        if(duplicate!=null){if(state.equals("VERIFIED")){Map<String,Object> previous=store.data(duplicate);previous.put("verifiedAt",store.clock.instant().toString());duplicate.setState("VERIFIED");store.save(PcTable.MEMORY,duplicate,previous);}if(target!=null)retireMemory(target);return memoryResult("DUPLICATE",entry(duplicate),List.of(),target==null?null:entry(target),scope,replace);}
        boolean allow=Boolean.TRUE.equals(input.get("allowConflict"))||Boolean.TRUE.equals(input.get("keep_both"));List<PcRecord> currentConflicts=domain.stream().filter(r->selected==null||!r.getId().equals(selected.getId())).filter(r->PcMemoryFacts.conflict(PcJson.text(store.data(r),"content"),fact)).toList();
        if(input.containsKey("conflictVersions")){Map<String,Object> versions=PcJson.object(input,"conflictVersions");Set<String> expected=new HashSet<>();for(PcRecord conflict:currentConflicts){String id=String.valueOf(conflict.getId());expected.add(id);if(!versions.containsKey(id)||PcJson.number(versions,id)!=conflict.getVersion())throw PcException.conflict("已审阅的冲突记忆版本变化，请重新核对");}if(!versions.keySet().equals(expected))throw PcException.conflict("已审阅的冲突记忆集合变化，请重新核对");}
        List<PcRecord> conflictRows=allow?List.of():currentConflicts;
        if(!conflictRows.isEmpty()){evidence.audit(workspace,user,task,session,"MEMORY_SAVE","CONFLICT",Map.of("contentHash",PcJson.digest(fact),"conflictIds",conflictRows.stream().map(PcRecord::getId).toList()));return memoryResult("CONFLICT",candidate(fact,scope),conflictRows.stream().map(this::entry).toList(),null,scope,replace);}
        String unique=(workspace==null?"user:"+user:"directory:"+workspace)+":"+PcJson.digest(PcMemoryFacts.canonicalize(fact));PcRecord row=store.mapper.findKey(PcTable.MEMORY,unique,true);if(row!=null&&(row.getWorkspaceId()!=null||row.getState().equals("FROZEN")||!Objects.equals(row.getOwnerId(),user)))throw new PcException(409,"PC_LEGACY_READ_ONLY","历史记忆已冻结，不能复用其唯一标识");if(target!=null)retireMemory(target);if(row==null)row=store.insert(PcTable.MEMORY,workspace,user,task,session,null,"MEMORY",state,unique,data);else{row.setState(state);store.save(PcTable.MEMORY,row,data);}store.insert(PcTable.MEMORY_VERSION,workspace,user,row.getId(),session,null,"MEMORY_VERSION","APPENDED",null,data);evidence.audit(workspace,user,task,session,"MEMORY_SAVE",state,Map.of("memoryId",row.getId(),"contentHash",row.getContentHash()));Map<String,Object> result=memoryResult(target!=null?"REPLACED":state.equals("VERIFIED")?"STORED":state,entry(row),List.of(),target==null?null:entry(target),scope,replace);result.put("memory",store.view(row));return result;
    }
    private void retireMemory(PcRecord row){row.setState("REPLACED");store.save(PcTable.MEMORY,row,store.data(row));}
    private Map<String,Object> candidate(String fact,String scope){Map<String,Object> result=new LinkedHashMap<>();result.put("id","candidate:"+PcJson.digest(fact));result.put("content",fact);result.put("type","fact");result.put("timestamp",store.clock.instant().toString());result.put("lastVerifiedAt",store.clock.instant().toString());result.put("tokenCount",Math.max(1,fact.length()/3));result.put("metadata",Map.of("scope",scope,"status","NOT_WRITTEN"));return result;}
    private Map<String,Object> memoryResult(String status,Map<String,Object> entry,List<Map<String,Object>> conflicts,Map<String,Object> replaced,String scope,String requested){Map<String,Object> result=new LinkedHashMap<>();result.put("status",status);result.put("entry",entry);result.put("conflicts",conflicts);result.put("replaced",replaced);result.put("scope",scope);result.put("requestedReplaceId",requested);return result;}
    public Map<String,Object> entry(PcRecord r){
        Map<String,Object> p=store.data(r),v=new LinkedHashMap<>();String content=PcJson.text(p,"content");
        String type=PcJson.text(p,"type").toUpperCase(Locale.ROOT);if(!Set.of("FACT","CONVERSATION","SUMMARY","TOOL_RESULT").contains(type))type="FACT";
        Map<String,Object> metadata=p.get("metadata") instanceof Map<?,?>?new LinkedHashMap<>(PcJson.object(p,"metadata")):new LinkedHashMap<>();
        metadata.put("scope",p.getOrDefault("scope","PROJECT"));metadata.put("status",r.getState());metadata.put("version",r.getVersion());metadata.put("source",p.getOrDefault("source","UNKNOWN"));
        if(!r.getState().equals("VERIFIED"))metadata.put("verification_pending","true");
        v.put("id",String.valueOf(r.getId()));v.put("content",content);v.put("fact",content);v.put("type",type);
        v.put("timestamp",p.getOrDefault("timestamp",p.getOrDefault("legacyOccurredAt",r.getCreatedAt().toString())));
        v.put("lastVerifiedAt",p.getOrDefault("verifiedAt",p.getOrDefault("lastVerifiedAt",v.get("timestamp"))));
        v.put("metadata",metadata);v.put("tokenCount",p.get("tokenCount") instanceof Number n?Math.max(0,n.longValue()):estimateTokens(content));
        v.put("scope",p.get("scope"));v.put("verified",r.getState().equals("VERIFIED"));v.put("version",r.getVersion());return v;
    }
    private static long estimateTokens(String text){long chinese=text.chars().filter(c->c>0x4E00&&c<0x9FFF).count();return (long)Math.ceil(chinese/1.5+(text.length()-chinese)/4.0);}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> action(long user,long id,long version,String key,String action,Map<String,Object> input){return idem.run("user:"+user+":memory:"+id+":"+action,key,input,()->{
        PcRecord row=access.resource(PcTable.MEMORY,id,user,false,true);if(row.getDirectoryContextId()==null&&!Objects.equals(row.getOwnerId(),user))throw PcException.deny("私有记忆只归本人");store.version(row,version);Map<String,Object> p=store.data(row);if(PcProjectRuleService.isRule(row,p))throw PcException.conflict("PAI规则请明确来源层及imports后使用规则登记入口，不能作为事实核实");
        switch(action){case "verify"->{row.setState("VERIFIED");p.put("verifiedAt",store.clock.instant().toString());}case "replace"->{String content=PcJson.text(input,"content");if(content.isBlank()||content.length()>8192)throw PcException.invalid("替代记忆不能为空或过大");String unique=(row.getDirectoryContextId()==null?"user:"+row.getOwnerId():"directory:"+row.getDirectoryContextId())+":"+PcJson.digest(PcMemoryFacts.canonicalize(content));PcRecord duplicate=store.mapper.findKey(PcTable.MEMORY,unique,true);if(duplicate!=null&&!duplicate.getId().equals(row.getId()))throw PcException.conflict("替换内容已由另一条记忆保存，请核对重复事实");row.setUniqueKey(unique);p.put("content",content);p.put("fact",content);p.put("tokenCount",estimateTokens(content));row.setState("PENDING");p.remove("verifiedAt");p.remove("conflictWith");}case "coexist"->{row.setState("PENDING");p.remove("conflictWith");p.put("coexistConfirmed",true);}case "delete"->row.setState("DELETED");default->throw PcException.invalid("记忆操作非法");}
        store.save(PcTable.MEMORY,row,p);store.insert(PcTable.MEMORY_VERSION,row.getDirectoryContextId(),user,id,row.getSessionId(),null,"MEMORY_VERSION","APPENDED",null,p);evidence.audit(row.getDirectoryContextId(),user,null,row.getSessionId(),"MEMORY_"+action.toUpperCase(Locale.ROOT),row.getState(),Map.of("memoryId",id,"version",row.getVersion()));return store.view(row);
    });}
    public Map<String,Object> index(long workspace,long user){access.directory(workspace,user,false);var rows=store.mapper.list(PcTable.INDEX_MANIFEST,workspace,null,null,null).stream().filter(r->r.getKind().equals("INDEX")).toList();if(rows.isEmpty())return Map.of("directoryContextId",String.valueOf(workspace),"status","MISSING","stale",true,"version",0);Map<String,Object> result=store.view(rows.get(0));result.putIfAbsent("stale",false);result.put("indexedAt",rows.get(0).getCreatedAt().toString());if(result.get("index") instanceof Map<?,?> statistics){for(String field:List.of("fileCount","chunkCount","relationCount","embeddingModel"))if(statistics.containsKey(field))result.put(field,statistics.get(field));}result.putIfAbsent("fileCount",null);result.putIfAbsent("embeddingModel",null);try{String hash=currentEmbeddingFingerprint(user);PcRecord directory=store.require(PcTable.DIRECTORY_CONTEXT,workspace,false);if(!hash.equals(result.get("embeddingFingerprint"))||!PcJson.text(store.data(directory),"rootFingerprint").equals(result.get("rootFingerprint"))){result.put("stale",true);result.put("status","REBUILD_REQUIRED");result.put("message","向量型号、维度、服务地址或目录身份改变，需要重建索引");}}catch(PcException unavailable){result.put("stale",true);result.put("status","EMBEDDING_UNAVAILABLE");result.put("message",unavailable.getMessage());}return result;}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> rebuild(long user,String key,long workspace){return idem.run("user:"+user+":index:"+workspace,key,Map.of("directoryContextId",workspace),()->sessions.control(user,workspace,onlineRunner(workspace,user),null,"INDEX_BUILD",Map.of()));}
    public long onlineRunner(long workspace,long user){PcRecord directory=access.directory(workspace,user,false);var rows=store.mapper.list(PcTable.RUNNER,null,user,null,"ONLINE").stream().filter(r->Objects.equals(r.getId(),directory.getRunnerId())).toList();if(rows.isEmpty())throw new PcException(503,"PC_RUNNER_OFFLINE","目录暂无在线Runner");return rows.get(0).getId();}
    @Transactional("paicliTransactionManager")
    public Object search(long workspace,long user,String query,String mode){access.directory(workspace,user,false);if(query.isBlank()||query.length()>2048||!Set.of("EXACT","SEMANTIC").contains(mode))throw PcException.invalid("搜索参数非法");String fingerprint=mode.equals("SEMANTIC")?requireSemanticIndex(workspace,user):"";long indexVersion=currentIndex(workspace);for(PcRecord row:store.mapper.list(PcTable.INDEX_MANIFEST,workspace,user,null,null)){Map<String,Object> p=store.data(row);if((!mode.equals("SEMANTIC")||fingerprint.equals(p.get("embeddingFingerprint"))&&PcJson.text(store.data(store.require(PcTable.DIRECTORY_CONTEXT,workspace,false)),"rootFingerprint").equals(p.get("rootFingerprint")))&&row.getKind().equals("SEARCH_RESULT")&&query.equals(p.get("query"))&&mode.equals(p.get("mode"))&&Objects.toString(p.get("indexVersion"),"").equals(String.valueOf(indexVersion)))return PcKnowledgeProjection.hits(p,indexVersion);}return queryTask(workspace,user,"REPOSITORY_SEARCH",query,mode,indexVersion);}
    @Transactional("paicliTransactionManager")
    public Object graph(long workspace,long user,String query){access.directory(workspace,user,false);if(query.isBlank()||query.length()>2048)throw PcException.invalid("关系图查询参数非法");long indexVersion=currentIndex(workspace);for(PcRecord row:store.mapper.list(PcTable.INDEX_MANIFEST,workspace,user,null,null)){Map<String,Object> p=store.data(row);if(row.getKind().equals("GRAPH_RESULT")&&query.equals(p.get("query"))&&Objects.toString(p.get("indexVersion"),"").equals(String.valueOf(indexVersion)))return PcKnowledgeProjection.graph(p,indexVersion);}return queryTask(workspace,user,"AST_GRAPH",query,"EXACT",indexVersion);}
    private String currentEmbeddingFingerprint(long user){PcEmbeddingPolicy.Selection selected=sessions.embeddingSelection(user);if(selected==null)throw new PcException(422,"PC_EMBEDDING_NOT_READY","向量检索未配置或已明确停用，精确搜索仍可使用");return PcEmbeddingPolicy.fingerprint(store,selected.config());}
    private String requireSemanticIndex(long directory,long user){String hash=currentEmbeddingFingerprint(user);Map<String,Object> manifest=index(directory,user);if(!hash.equals(manifest.get("embeddingFingerprint"))||Boolean.TRUE.equals(manifest.get("stale"))||!"READY".equals(manifest.get("status")))throw new PcException(409,"PC_INDEX_REBUILD_REQUIRED","当前向量身份没有有效代码索引，请先重建；精确搜索仍可使用");return hash;}
    private long currentIndex(long workspace){var rows=store.mapper.list(PcTable.INDEX_MANIFEST,workspace,null,null,null).stream().filter(r->r.getKind().equals("INDEX")).toList();return rows.isEmpty()?0:rows.get(0).getId();}
    private Map<String,Object> queryTask(long workspace,long user,String operation,String query,String mode,long indexVersion){String unique="query:"+PcJson.digest(workspace+":"+user+":"+operation+":"+query+":"+mode+":"+indexVersion);PcRecord previous=store.mapper.findKey(PcTable.TASK,unique,true);if(previous==null){access.directory(workspace,user,true);Map<String,Object> submitted=sessions.control(user,workspace,onlineRunner(workspace,user),null,operation,Map.of("query",query,"mode",mode,"limit",50,"indexVersion",indexVersion));previous=store.require(PcTable.TASK,PcJson.number(submitted,"id"),true);previous.setUniqueKey(unique);store.save(PcTable.TASK,previous,store.data(previous));}if(Set.of("FAILED","CANCELLED","RECONCILE_REQUIRED").contains(previous.getState()))throw new PcException(422,"PC_QUERY_FAILED","查询任务未完成，请核对任务 "+previous.getId()+" 后重新重建索引或提交明确新查询");return Map.of("status","PENDING","taskId",String.valueOf(previous.getId()),"sessionId",String.valueOf(previous.getSessionId()),"message","Runner正在执行授权仓库查询");}
    public List<Map<String,Object>> snapshots(long session,long user){PcRecord s=access.resource(PcTable.SESSION,session,user,true,false);List<Map<String,Object>> result=new ArrayList<>();int restoreOrdinal=0;for(PcRecord row:store.mapper.list(PcTable.SNAPSHOT,s.getDirectoryContextId(),user,null,null).stream().sorted(Comparator.comparing(PcRecord::getCreatedAt,Comparator.nullsLast(Comparator.reverseOrder())).thenComparing(PcRecord::getId,Comparator.reverseOrder())).toList())if(Objects.equals(row.getSessionId(),session)&&!row.getState().equals("REVOKED_IMPORT")){Map<String,Object> item=store.view(row);item.put("ordinal",result.size()+1);if("PRE_TURN".equals(PcJson.text(item,"phase").toUpperCase(Locale.ROOT).replace('-','_'))){item.put("restoreOrdinal",++restoreOrdinal);item.put("restoreHint","/restore "+restoreOrdinal);}result.add(item);}return result;}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> requestPreview(long user,long id,long version,String key){return idem.run("user:"+user+":snapshot-preview:"+id,key,Map.of("version",version),()->{PcRecord snap=access.resource(PcTable.SNAPSHOT,id,user,true,true);store.version(snap,version);return sessions.control(user,snap.getDirectoryContextId(),snap.getRunnerId(),snap.getSessionId(),"SNAPSHOT_PREVIEW",snapshotArguments(snap));});}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> cleanAll(long user,String key){return idem.run("user:"+user+":snapshot-clean-all",key,Map.of("range","all"),()->{List<Map<String,Object>> tasks=new ArrayList<>(),blocked=new ArrayList<>();for(PcRecord workspace:store.mapper.visibleWorkspaces(user)){if(!workspace.getState().equals("VERIFIED")){blocked.add(Map.of("directoryContextId",String.valueOf(workspace.getId()),"reason","目录未启用"));continue;}var runners=store.mapper.list(PcTable.RUNNER,null,user,null,"ONLINE").stream().filter(r->Objects.equals(r.getId(),workspace.getRunnerId())).toList();if(runners.isEmpty()){blocked.add(Map.of("directoryContextId",String.valueOf(workspace.getId()),"reason","暂无在线Runner"));continue;}tasks.add(cleanCurrent(user,workspace.getId(),runners.get(0).getId(),null));}return Map.of("status",blocked.isEmpty()?"QUEUED":tasks.isEmpty()?"BLOCKED":"PARTIAL","tasks",tasks,"blocked",blocked,"range","all","message","逐个人目录预览完整缓存后独立批准；每次执行只清当前root且先保留私有恢复备份");});}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> cleanCurrent(long user,long workspace,long runner,Long session){access.directory(workspace,user,true);PcSnapshotClean cleanup=new PcSnapshotClean(store);for(PcRecord row:store.mapper.list(PcTable.SNAPSHOT,workspace,user,null,"DERIVED_READY")){if(!row.getKind().equals("CLEAN_PREVIEW")||!Objects.equals(row.getRunnerId(),runner))continue;boolean confirmed=store.mapper.list(PcTable.TOOL_RECEIPT,workspace,user,row.getParentId(),"COMPLETED").stream().anyMatch(receipt->"control__SNAPSHOT_CLEAN_PREVIEW".equals(receipt.getKind()));if(!confirmed)continue;Map<String,Object> data=store.data(row);if(row.getExpiresAt()==null||!row.getExpiresAt().isAfter(store.clock.instant())){row.setState("PREVIEW_EXPIRED");store.save(PcTable.SNAPSHOT,row,data);continue;}Map<String,Object> arguments=PcJson.object(data,"frozenArguments");arguments.put("cleanPreview",PcJson.object(data,"cleanPreview"));try{cleanup.validate(row,arguments);}catch(PcException stale){row.setState("PREVIEW_INVALIDATED");store.save(PcTable.SNAPSHOT,row,data);continue;}Map<String,Object> policy=store.data(store.policy(workspace,false));arguments.put("cleanPreviewRecordId",row.getId().toString());arguments.put("backupPolicy",Map.of("location","RUNNER_PRIVATE_ARCHIVE","retentionDays",policy.getOrDefault("retentionDays",90),"restorable",true,"description","清理前原子归档完整派生仓库；原始快照内容、缓存清单和SHA可按备份恢复说明恢复"));Map<String,Object> task=sessions.control(user,workspace,runner,session,"SNAPSHOT_CLEAN",arguments);data.put("cleanupTaskId",task.get("id"));row.setState("BOUND_CLEANUP");store.save(PcTable.SNAPSHOT,row,data);return task;}Map<String,Object> task=new LinkedHashMap<>(sessions.control(user,workspace,runner,session,"SNAPSHOT_CLEAN_PREVIEW",cleanup.previewArguments(workspace,runner)));task.put("cleanPreviewRequired",true);task.put("previewTaskId",task.get("id"));task.put("taskId",task.get("id"));return task;}
    private Map<String,Object> snapshotArguments(PcRecord snap){Map<String,Object> data=store.data(snap);String commit=PcJson.text(data,"commitId");if(commit.isBlank())commit=PcJson.text(data,"snapshotId");if(!commit.matches("[a-f0-9]{40,64}")||snap.getRunnerId()==null||snap.getSessionId()==null)throw PcException.conflict("快照没有当前Runner的真实commit证据，不能执行恢复");Map<String,Object> args=new LinkedHashMap<>();args.put("snapshotId",commit);args.put("snapshotMetadataId",String.valueOf(snap.getId()));args.put("snapshot",data);args.put("version",snap.getVersion());return args;}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> restore(long user,long id,long version,String key,Map<String,Object> input){return idem.run("user:"+user+":restore:"+id,key,Map.of("version",version,"input",input),()->{PcRecord snap=access.resource(PcTable.SNAPSHOT,id,user,true,true);store.version(snap,version);String fingerprint=PcJson.text(input,"currentFingerprint");Map<String,Object> proof=preview(user,id);if(!fingerprint.matches("[a-f0-9]{64}")||!Objects.equals(fingerprint,proof.get("currentFingerprint"))||!Boolean.TRUE.equals(proof.get("canRestore")))throw PcException.conflict("恢复必须绑定已核对且无冲突的当前文件指纹");Map<String,Object> args=snapshotArguments(snap);args.put("currentFingerprint",fingerprint);return sessions.control(user,snap.getDirectoryContextId(),snap.getRunnerId(),snap.getSessionId(),"SNAPSHOT_RESTORE",args);});}
    public Map<String,Object> preview(long user,long id){PcRecord snap=access.resource(PcTable.SNAPSHOT,id,user,true,false);Map<String,Object> p=store.data(snap);if(p.get("restorePreview") instanceof Map<?,?> raw){Map<String,Object> result=new LinkedHashMap<>();raw.forEach((k,v)->result.put(String.valueOf(k),v));result.put("snapshotId",String.valueOf(id));result.put("version",snap.getVersion());return result;}throw new PcException(503,"PC_RESTORE_PREVIEW_REQUIRED","请先派发快照预览，由绑定Runner报告当前文件指纹和实际差异");}
}
